$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$script=Join-Path $root 'classify-result.ps1';$tmp=Join-Path $env:TEMP ('flcad-classify-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $tmp|Out-Null
function W($p,$o){$o|ConvertTo-Json -Depth 8|Set-Content $p -Encoding UTF8};function A([bool]$c,[string]$m){if(!$c){throw "ASSERTION FAILED: $m"}}
function Base($id='CLASSIFY-DEMO'){@{schema_version='1.0';task_id=$id;execution_status='completed';criteria_verified=$true;review_required=$false;professional_test_required=$false;approval_required=$false;critical_decision_required=$false;blocked=$false;dependency_unavailable=$false;gui_authorization_required=$false;security_failure=$false}}
function Run($o){$p=Join-Path $tmp ([guid]::NewGuid().ToString('N')+'.json');W $p $o;(& powershell -NoProfile -ExecutionPolicy Bypass -File $script -InputJson $p|ConvertFrom-Json)}
try{$x=Run (Base);A($x.classification-eq'COMPLETED'-and$x.notification_required-eq$false-and$x.event-eq'NONE')'completed must not notify';$x=Base;$x.review_required=$true;$y=Run $x;A($y.classification-eq'READY_FOR_REVIEW'-and$y.notification_required-eq$false)'review must not notify';$x=Base;$x.professional_test_required=$true;$x.reason='Professional test is required';$x.action_requested='Perform professional test';$y=Run $x;A($y.classification-eq'WAITING_FOR_USER'-and$y.event-eq'USER_TEST_REQUIRED')'professional test event';$x=Base;$x.approval_required=$true;$x.reason='Approval is required';$x.action_requested='Approve the result';$y=Run $x;A($y.event-eq'USER_APPROVAL_REQUIRED')'approval event';$x=Base;$x.blocked=$true;$y=Run $x;A($y.classification-eq'BLOCKED'-and$y.event-eq'AGENT_BLOCKED')'blocked event';$x=Base;$x.gui_authorization_required=$true;$y=Run $x;A($y.classification-eq'BLOCKED'-and$y.event-eq'AGENT_BLOCKED');$x=Base;$x['command']='Invoke-Expression';W (Join-Path $tmp 'bad.json') $x;$old=$ErrorActionPreference;$ErrorActionPreference='Continue';& powershell -NoProfile -ExecutionPolicy Bypass -File $script -InputJson (Join-Path $tmp 'bad.json') 2>&1|Out-Null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;A($code-ne0)'external command must be rejected';Write-Output 'classification.tests.ps1: PASS'}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}
